package egautogen_test

import (
	"testing"

	"github.com/egdaemon/eg/runtime/x/wasi/egautogen"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestPaths(t *testing.T) {
	t.Run("returns a single filter for one glob", func(t *testing.T) {
		f := egautogen.Paths("*.go")
		require.Len(t, f, 1)
		sql, args, err := f.ToSql()
		require.NoError(t, err)
		require.NotEmpty(t, sql)
		require.Len(t, args, 1)
	})

	t.Run("returns a single filter for multiple globs", func(t *testing.T) {
		f := egautogen.Paths("a/*.go", "b/**/*.go", "c.go")
		require.Len(t, f, 1)
		sql, args, err := f.ToSql()
		require.NoError(t, err)
		require.NotEmpty(t, sql)
		require.Len(t, args, 3)
	})

	t.Run("produces the same result as the Filters method", func(t *testing.T) {
		globs := []string{"x/*.go", "y/*.go"}
		fromFunc := egautogen.Paths(globs...)
		fromMethod := egautogen.Filters(nil).Paths(globs...)
		sqlA, argsA, errA := fromFunc.ToSql()
		sqlB, argsB, errB := fromMethod.ToSql()
		require.Equal(t, errB, errA)
		require.Equal(t, sqlB, sqlA)
		require.Equal(t, argsB, argsA)
	})
}
